import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.CZo9GF0W.js";const u=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md","lastUpdated":1789060268000}'),r={name:"guide/settings.md"};function c(i,t,s,n,h,l){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Everything is namespaced under <code>pitta.</code>. Open <strong>Preferences: Open Settings</strong> and filter on <code>pitta</code>, or edit <code>settings.json</code> directly.</p><p>Settings apply per user by default and can be overridden per workspace — except the guard settings, which VS Code refuses to take from an untrusted workspace so a cloned repository cannot turn them off. See <a href="./safety#untrusted-workspaces">Safety</a>.</p><h2 id="safety" tabindex="-1">Safety <a class="header-anchor" href="#safety" aria-label="Permalink to &quot;Safety&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>pitta.query.confirmDestructive</code></td><td><code>prod</code></td><td>Which environments confirm before <code>DROP</code> / <code>TRUNCATE</code> / unqualified DML. The typed confirmation on <code>prod</code> cannot be turned off.</td></tr><tr><td><code>pitta.query.blockUnqualifiedDml</code></td><td><code>true</code></td><td>Refuse <code>UPDATE</code>/<code>DELETE</code> with no <code>WHERE</code>, on any connection.</td></tr><tr><td><code>pitta.query.statementTimeoutMs</code></td><td><code>0</code></td><td>Server-side statement timeout. <code>0</code> disables it.</td></tr><tr><td><code>pitta.query.autocommit</code></td><td><code>true</code></td><td>Run statements outside an explicit transaction.</td></tr><tr><td><code>pitta.redis.allowKeysCommand</code></td><td><code>false</code></td><td>Allow <code>KEYS</code>. It walks the whole keyspace and blocks the server while it does; the tree uses <code>SCAN</code> instead.</td></tr><tr><td><code>pitta.redis.allowMonitor</code></td><td><code>false</code></td><td>Allow <code>MONITOR</code>. It makes the server report every command to this client and measurably slows it for everyone. Refused on production whatever this is set to.</td></tr><tr><td><code>pitta.redis.monitorSeconds</code></td><td><code>10</code></td><td>How long <code>MONITOR</code> runs before stopping itself.</td></tr></tbody></table><h2 id="results-and-memory" tabindex="-1">Results and memory <a class="header-anchor" href="#results-and-memory" aria-label="Permalink to &quot;Results and memory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>pitta.defaultFetchSize</code></td><td><code>500</code></td><td>Rows fetched per page from a server-side cursor.</td></tr><tr><td><code>pitta.query.streamResults</code></td><td><code>true</code></td><td>Keep the cursor open after the first page and read on as you scroll. Turning it off reads up to <code>pitta.maxRowsInMemory</code> before the first row appears.</td></tr><tr><td><code>pitta.maxRowsInMemory</code></td><td><code>50000</code></td><td>Rows a result keeps before it is marked truncated. Costs roughly <strong>0.5 KB per row per 20 columns</strong>, so the default caps an accidental <code>SELECT *</code> at about 27 MB.</td></tr><tr><td><code>pitta.gridCacheBudgetMB</code></td><td><code>200</code></td><td>Memory budget for cached result pages; the oldest are evicted first.</td></tr></tbody></table><p>Exports and imports stream to and from disk and are not bounded by any of these. A table larger than memory exports fine.</p><h2 id="explorer" tabindex="-1">Explorer <a class="header-anchor" href="#explorer" aria-label="Permalink to &quot;Explorer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>pitta.explorer.pageSize</code></td><td><code>500</code></td><td>Objects per level before a <strong>Show more</strong> entry. VS Code virtualizes rendering, but handing it tens of thousands of items still costs a call each as you scroll.</td></tr><tr><td><code>pitta.explorer.showSystemObjects</code></td><td><code>false</code></td><td>Show <code>pg_catalog</code> and <code>information_schema</code>.</td></tr><tr><td><code>pitta.explorer.rowCountMode</code></td><td><code>estimate</code></td><td><code>estimate</code> reads the catalog&#39;s row estimate and is free. <code>exact</code> runs <code>COUNT(*)</code> — accurate, and a full scan on a large table.</td></tr><tr><td><code>pitta.metadataCacheTtlSeconds</code></td><td><code>300</code></td><td>Schema cache lifetime. <code>0</code> re-reads the catalog every time. The cache is also invalidated eagerly when Pitta runs DDL itself.</td></tr></tbody></table><h2 id="editor" tabindex="-1">Editor <a class="header-anchor" href="#editor" aria-label="Permalink to &quot;Editor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>pitta.editor.completion</code></td><td><code>true</code></td><td>Suggest tables, columns and functions from the bound connection.</td></tr><tr><td><code>pitta.editor.diagnostics</code></td><td><code>semantic</code></td><td><code>off</code>, <code>syntax</code> (grammar only), or <code>semantic</code> (adds unknown-name and type checks against the catalog).</td></tr><tr><td><code>pitta.editor.diagnosticsDelayMs</code></td><td><code>400</code></td><td>Pause after typing before diagnostics run.</td></tr><tr><td><code>pitta.editor.formatOnSave</code></td><td><code>false</code></td><td>Format <code>.sql</code> files bound to a Pitta connection on save.</td></tr><tr><td><code>pitta.editor.keywordCase</code></td><td><code>upper</code></td><td>Keyword case the formatter produces.</td></tr><tr><td><code>pitta.editor.maxLineLength</code></td><td><code>100</code></td><td>Length past which the formatter breaks a comma-separated list.</td></tr></tbody></table><h2 id="history-and-saved-queries" tabindex="-1">History and saved queries <a class="header-anchor" href="#history-and-saved-queries" aria-label="Permalink to &quot;History and saved queries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>pitta.history.enabled</code></td><td><code>true</code></td><td>Record executed statements locally.</td></tr><tr><td><code>pitta.history.excludeEnvironments</code></td><td><code>[&quot;prod&quot;]</code></td><td>Environments kept out of history entirely.</td></tr><tr><td><code>pitta.history.maxEntries</code></td><td><code>5000</code></td><td>Entries kept before the oldest are dropped.</td></tr><tr><td><code>pitta.savedQueries.folder</code></td><td><code>.pitta/queries</code></td><td>Workspace folder holding saved <code>.sql</code> files.</td></tr></tbody></table><h2 id="diagnostics-and-privacy" tabindex="-1">Diagnostics and privacy <a class="header-anchor" href="#diagnostics-and-privacy" aria-label="Permalink to &quot;Diagnostics and privacy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>pitta.logLevel</code></td><td><code>info</code></td><td>Verbosity of the Pitta output channel: <code>trace</code>, <code>debug</code>, <code>info</code>, <code>warn</code>, <code>error</code>, <code>off</code>. Set <code>debug</code> before reporting a bug.</td></tr><tr><td><code>pitta.telemetry.enabled</code></td><td><code>false</code></td><td>Off. Nothing is collected or transmitted.</td></tr></tbody></table><h2 id="per-connection-overrides" tabindex="-1">Per-connection overrides <a class="header-anchor" href="#per-connection-overrides" aria-label="Permalink to &quot;Per-connection overrides&quot;">​</a></h2><p>Some of these are also profile fields, and the profile wins for that connection: statement timeout, fetch size, autocommit, <code>search_path</code>, <code>TimeZone</code> and <code>application_name</code>. Set them on the profile when they belong to the server rather than to you.</p>',18)])])}const f=e(r,[["render",c]]);export{u as __pageData,f as default};
